import re

with open('/tmp/dhr_10q_full.htm', 'r', encoding='utf-8') as f:
    content = f.read()

# Find ALL ix:nonFraction tags to get more data
pattern = r'<ix:nonFraction[^>]*name="([^"]+)"[^>]*>([^<]+)</ix:nonFraction>'
matches = re.findall(pattern, content)

# Print ALL values to find revenue
key_metrics = {}
for name, value in matches:
    if name not in key_metrics:
        key_metrics[name] = []
    key_metrics[name].append(value)

# Print Revenues-related tags
for name, values in sorted(key_metrics.items()):
    if 'Reven' in name or 'Sales' in name or 'Revenue' in name:
        unique = list(dict.fromkeys(values))  # preserve order, remove dupes
        print(f"{name}: {unique}")

# Also look for segment data
print("\n\n--- Looking for segment data ---")
for name, values in sorted(key_metrics.items()):
    if 'segment' in name.lower() or 'Product' in name or 'Life' in name or 'Diagnostic' in name or 'Water' in name:
        unique = list(dict.fromkeys(values))
        print(f"{name}: {unique}")
EOF"}

